  END IF;
END $$;

CREATE TABLE pricing_decision (
  subscription_id text PRIMARY KEY REFERENCES subscription(id),
  decision_date date NOT NULL,
  fee_cents integer NOT NULL CHECK (fee_cents >= 0)
);

INSERT INTO pricing_decision (subscription_id, decision_date, fee_cents)
SELECT s.id, s.approved_at,
       COALESCE(h.fee_cents, (s.terms->>'monthlyFeeCents')::integer, 100)
FROM subscription s
LEFT JOIN LATERAL (
  SELECT fee_cents FROM pricing_history
  WHERE subscription_id = s.id AND effective_from <= s.approved_at
  ORDER BY effective_from DESC
  LIMIT 1
) h ON true;

