export const MIN_FEE = 100;

export function getFee(subscription: any) {
  return subscription.pricingDecision?.feeCents ?? MIN_FEE;
}

export function newVersion(previous: any) {
  const { monthlyFeeCents: _legacyFee, ...terms } = previous.terms ?? {};
  return { terms };
}

export function changedSinceApproval(subscription: any) {
  return subscription.pricingDecision != null &&
    subscription.terms.monthlyFeeCents != null &&
    getFee(subscription) !== subscription.terms.monthlyFeeCents;
}

export function acceptLegacyTerms(input: any) {
  if (input.monthlyFeeCents !== undefined &&
      (!Number.isInteger(input.monthlyFeeCents) || input.monthlyFeeCents < 0)) {
    throw new Error('invalid');
  }
  const { monthlyFeeCents: _legacyFee, ...terms } = input;
  return terms;
}
